/**
 * Checks that the generated output and its source have not diverged.
 *
 * Every package's `package.json`, `README.md`, `LICENSE` and `tsup.config.ts` is
 * generated by `scaffold.mjs` from `registry.mjs`. Nothing stops someone editing
 * the output by hand, after which it silently disagrees with the source: the
 * registry says one thing, the published package another, and the consumer finds
 * out.
 *
 * One check catching exactly one case: the working tree changed after running
 * the scaffolder. A declaration nothing is built from is a second truth, free to
 * describe itself however it likes.
 */
import { execFileSync } from "node:child_process";

const run = (cmd, args) =>
	execFileSync(cmd, args, {
		encoding: "utf8",
		stdio: ["ignore", "pipe", "pipe"],
		// On Windows the `pnpm` executable is `pnpm.cmd`, which `execFileSync`
		// cannot find without `shell`.
		shell: process.platform === "win32",
	});

const dirtyBefore = run("git", ["status", "--porcelain"]).trim();
if (dirtyBefore.length > 0) {
	// Otherwise the check reports someone's uncommitted edit as drift — lying at
	// exactly the moment it is trusted most.
	console.error(
		"The working tree is not clean, and this check compares exactly that.\n" +
			"Commit or stash your changes and try again:\n\n" +
			dirtyBefore,
	);
	process.exit(1);
}

run("node", ["scripts/scaffold.mjs"]);

const drift = run("git", ["status", "--porcelain"]).trim();
if (drift.length === 0) {
	console.log("registry and generated output agree");
	process.exit(0);
}

const diff = run("git", ["diff"]);
console.error(
	"REGISTRY AND GENERATED OUTPUT HAVE DIVERGED.\n\n" +
		"These files are written by `scripts/scaffold.mjs` from `scripts/registry.mjs`.\n" +
		"A hand edit will not survive the next run — edit the registry instead:\n\n" +
		drift +
		"\n\n" +
		diff,
);
process.exit(1);
